const data = $input.first().json;

const emaCurrent = data.ema_current_status || 'UNKNOWN';
const emaCurrentTime = data.ema_current_time ? new Date(data.ema_current_time).getTime() : 0;
const emaPrev = data.ema_prev_status || 'UNKNOWN';
const emaPrevDurationSeconds = data.ema_prev_duration_seconds || 0;

const actCurrent = data.act_current_status || 'UNKNOWN';
const actStatusSeconds = data.act_status_seconds || 0;

const now = Date.now();
// Segundos transcurridos desde que se insertó el registro actual de EMA
const secondsSinceEmaLog = emaCurrentTime > 0 ? Math.floor((now - emaCurrentTime) / 1000) : 999999;

let alertType = 'NONE';
let message = '';

// 1. CASO BATERÍA AGOTADA O APAGÓN:
// El nodo EMA debe llevar en OFFLINE continuo entre 10 y 11 minutos (600 a 660 segundos).
// Se dispara EXACTAMENTE UNA VEZ cuando secondsSinceEmaLog entra en la ventana [600, 660].
if (emaCurrent === 'OFFLINE' && secondsSinceEmaLog >= 600 && secondsSinceEmaLog < 660) {
  if (actCurrent === 'OFFLINE' && actStatusSeconds >= 300) {
    alertType = 'SIN_CONEXION_WIFI';
    message = '\u200B\n*Sin Conexión WiFi*\n\n*Nodo EMA:* OFFLINE\n*Nodo Actuador:* OFFLINE';
  } else {
    alertType = 'BATERIA_AGOTADA';
    message = '\u200B\n*Bateria Agotada*\n\n*Nodo EMA:* OFFLINE';
  }
}
// 2. CASO RESTABLECIMIENTO:
// Se dispara ÚNICAMENTE si el registro actual es NUEVO (insertado en los últimos 60 segundos)
// Y el estado previo fue un OFFLINE REAL/CONFIRMADO (que duró >= 10 minutos / 600 segundos).
// Si fue una micro-caída de segundos/minutos (< 600s), NO se notifica restablecimiento porque nunca hubo alerta de caída.
else if (
  (emaCurrent === 'ONLINE' || emaCurrent === 'SLEEP') &&
  emaPrev === 'OFFLINE' &&
  secondsSinceEmaLog >= 0 &&
  secondsSinceEmaLog <= 60 &&
  emaPrevDurationSeconds >= 600
) {
  alertType = 'EMA_RESTABLECIDO';
  message = '\u200B\n*Nodo EMA* Operativo.';
}

if (alertType === 'NONE') {
  return [];
}

return [{ json: { alertType, message } }];
